{
  "assessment_outcome": "does_not_meet_standard",
  "explanation": "The patient fails to meet both unconditional and conditional licensing standards. The verified facts confirm the presence of insulin-treated diabetes, which explicitly excludes eligibility for an unconditional licence per guideline AFTD2022-DM-COM-007. Furthermore, the patient has confirmed non-physiological diplopia within 20 degrees of central fixation, a finding that explicitly excludes eligibility for both unconditional and conditional licences per guideline AFTD2022-VIS-COM-007. The nurse note regarding unassessed lens changes or glucose control does not override these explicit exclusionary findings.",
  "criterion_checks": [
    {
      "module": "diabetes",
      "passage_id": "PASS-214ce917afb61156d421eb7b",
      "fact_fields": ["diabetes.present", "diabetes.treatment_category"],
      "licence_pathway": "unconditional",
      "finding": "established_restriction",
      "conclusion": "The patient has insulin-treated diabetes (present=true, treatment=insulin). Guideline AFTD2022-DM-COM-007 states a person is not fit for an unconditional licence if they have insulin-treated diabetes. This criterion is met, resulting in exclusion from the unconditional pathway."
    },
    {
      "module": "vision",
      "passage_id": "PASS-8da032d63c954c0ce3d82598",
      "fact_fields": ["vision.diplopia.present", "vision.diplopia.physiological", "vision.diplopia.within_20_degrees"],
      "licence_pathway": "unconditional",
      "finding": "established_restriction",
      "conclusion": "The patient has non-physiological diplopia within 20 degrees of central fixation (present=true, physiological=false, within_20_degrees=true). Guideline AFTD2022-VIS-COM-007 states a person is not fit for an unconditional or conditional licence if they experience such diplopia. This criterion is met, resulting in exclusion from both unconditional and conditional pathways."
    }
  ]
}
